import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

for bp, ap in zip(baseline['projects'], after['projects']):
    proj = bp['path'].split('/')[-2]
    bpkgs = {p['id']: p['resolvedVersion'] for p in bp['frameworks'][0]['topLevelPackages']}
    apkgs = {p['id']: p['resolvedVersion'] for p in ap['frameworks'][0]['topLevelPackages']}
    changes = [(k,bpkgs[k],apkgs[k]) for k in bpkgs if bpkgs.get(k) != apkgs.get(k)]
    if changes:
        for pkg, old, new in changes:
            print(f'{proj}: {pkg} {old} -> {new}')
    else:
        print(f'{proj}: unchanged')
"

